1// Template to perform linear search on a vector.
2template<typename T>
3int linear_search(const vector<T>& arr, T target) {
4    
5    // Iterate through all elements in the vector.
6    for(int i = 0; i < arr.size(); ++i) {
7        // Check if the current element matches the target.
8        if(arr[i] == target)
9            // Return the index of the element if found.
10            return i; 
11    }
12    // Return -1 if the target is not found.
13    return -1; 
14}
